static u8 *__hid_alloc_report_buf(struct hid_report *report, u32 len, gfp_t flags)
{
	/*
	 * 7 extra bytes are necessary to achieve proper functionality
	 * of implement() working on 8 byte chunks
	 * 1 extra byte for the report ID if it is null (not used) so
	 * we can reserve that extra byte in the first position of the buffer
	 * when sending it to .raw_request()
	 */
	u32 alloc_len = len + 7 + (report->id == 0);

	return kzalloc(alloc_len, flags);
}

u8 *hid_alloc_report_buf(struct hid_report *report, gfp_t flags)
{
	return __hid_alloc_report_buf(report, hid_report_len(report), flags);
}

