+   673	/*
+   674	 * Process a reserved item.
+   675	 */
+   676	
+   677	static int hid_parser_reserved(struct hid_parser *parser, struct hid_item *item)
+   678	{
+   679		dbg_hid("reserved item type, tag 0x%x\n", item->tag);
+   680		return 0;
+   681	}
