+  1301			ret = -ENOMEM;
+  1302			goto alloc_err;
+  1303		}
+  1304	
+  1305		parser->device = device;
+  1306	
+  1307		end = start + size;
+  1308	
+  1309		device->collection = kcalloc(HID_DEFAULT_NUM_COLLECTIONS,
+  1310					     sizeof(struct hid_collection), GFP_KERNEL);
+  1311		if (!device->collection) {
