+  1470	/*
+  1471	 * Search an array for a value.
+  1472	 */
+  1473	
+  1474	static int search(__s32 *array, __s32 value, unsigned n)
+  1475	{
+  1476		while (n--) {
+  1477			if (*array++ == value)
+  1478				return 0;
+  1479		}
+  1480		return -1;
+  1481	}
