+  1972	/*
+  1973	 * Implement a generic .request() callback, using .raw_request()
+  1974	 * DO NOT USE in hid drivers directly, but through hid_hw_request instead.
+  1975	 */
+  1976	int __hid_request(struct hid_device *hid, struct hid_report *report,
+  1977			enum hid_class_request reqtype)
+  1978	{
+  1979		char *buf;
+  1980		int ret;
+  1981		u32 len;
+  1982	
+  1983		buf = hid_alloc_report_buf(report, GFP_KERNEL);
+  1984		if (!buf)
+  1985			return -ENOMEM;
+  1986	
+  1987		len = hid_report_len(report);
+  1988	
+  1989		if (reqtype == HID_REQ_SET_REPORT)
+  1990			hid_output_report(report, buf);
+  1991	
+  1992		ret = hid->ll_driver->raw_request(hid, report->id, buf, len,
+  1993						  report->type, reqtype);
+  1994		if (ret < 0) {
+  1995			dbg_hid("unable to complete request: %d\n", ret);
+  1996			goto out;
+  1997		}
+  1998	
+  1999		if (reqtype == HID_REQ_GET_REPORT)
+  2000			hid_input_report(hid, report->type, buf, ret, 0);
+  2001	
+  2002		ret = 0;
+  2003	
+  2004	out:
+  2005		kfree(buf);
+  2006		return ret;
+  2007	}
+  2008	EXPORT_SYMBOL_GPL(__hid_request);
