+  2010	int hid_report_raw_event(struct hid_device *hid, enum hid_report_type type, u8 *data, u32 size,
+  2011				 int interrupt)
+  2012	{
+  2013		struct hid_report_enum *report_enum = hid->report_enum + type;
+  2014		struct hid_report *report;
+  2015		struct hid_driver *hdrv;
+  2016		int max_buffer_size = HID_MAX_BUFFER_SIZE;
+  2017		u32 rsize, csize = size;
+  2018		u8 *cdata = data;
+  2019		int ret = 0;
+  2020	
+  2021		report = hid_get_report(report_enum, data);
+  2022		if (!report)
+  2023			goto out;
+  2024	
+  2025		if (report_enum->numbered) {
+  2026			cdata++;
+  2027			csize--;
+  2028		}
+  2029	
+  2030		rsize = hid_compute_report_size(report);
+  2031	
+  2032		if (hid->ll_driver->max_buffer_size)
+  2033			max_buffer_size = hid->ll_driver->max_buffer_size;
+  2034	
+  2035		if (report_enum->numbered && rsize >= max_buffer_size)
+  2036			rsize = max_buffer_size - 1;
+  2037		else if (rsize > max_buffer_size)
+  2038			rsize = max_buffer_size;
+  2039	
+  2040		if (csize < rsize) {
+  2041			dbg_hid("report %d is too short, (%d < %d)\n", report->id,
+  2042					csize, rsize);
+  2043			memset(cdata + csize, 0, rsize - csize);
+  2044		}
+  2045	
+  2046		if ((hid->claimed & HID_CLAIMED_HIDDEV) && hid->hiddev_report_event)
+  2047			hid->hiddev_report_event(hid, report);
+  2048		if (hid->claimed & HID_CLAIMED_HIDRAW) {
+  2049			ret = hidraw_report_event(hid, data, size);
+  2050			if (ret)
+  2051				goto out;
+  2052		}
+  2053	
+  2054		if (hid->claimed != HID_CLAIMED_HIDRAW && report->maxfield) {
+  2055			hid_process_report(hid, report, cdata, interrupt);
+  2056			hdrv = hid->driver;
+  2057			if (hdrv && hdrv->report)
+  2058				hdrv->report(hid, report);
+  2059		}
+  2060	
+  2061		if (hid->claimed & HID_CLAIMED_INPUT)
+  2062			hidinput_report_event(hid, report);
+  2063	out:
+  2064		return ret;
+  2065	}
+  2066	EXPORT_SYMBOL_GPL(hid_report_raw_event);
+  2067	
