+  2069	static int __hid_input_report(struct hid_device *hid, enum hid_report_type type,
+  2070				      u8 *data, u32 size, int interrupt, u64 source, bool from_bpf,
+  2071				      bool lock_already_taken)
+  2072	{
+  2073		struct hid_report_enum *report_enum;
+  2074		struct hid_driver *hdrv;
+  2075		struct hid_report *report;
+  2076		int ret = 0;
+  2077	
+  2078		if (!hid)
+  2079			return -ENODEV;
+  2080	
+  2081		ret = down_trylock(&hid->driver_input_lock);
+  2082		if (lock_already_taken && !ret) {
+  2083			up(&hid->driver_input_lock);
+  2084			return -EINVAL;
+  2085		} else if (!lock_already_taken && ret) {
+  2086			return -EBUSY;
+  2087		}
+  2088	
+  2089		if (!hid->driver) {
+  2090			ret = -ENODEV;
+  2091			goto unlock;
+  2092		}
+  2093		report_enum = hid->report_enum + type;
+  2094		hdrv = hid->driver;
+  2095	
+  2096		data = dispatch_hid_bpf_device_event(hid, type, data, &size, interrupt, source, from_bpf);
+  2097		if (IS_ERR(data)) {
+  2098			ret = PTR_ERR(data);
+  2099			goto unlock;
+  2100		}
+  2101	
+  2102		if (!size) {
+  2103			dbg_hid("empty report\n");
+  2104			ret = -1;
+  2105			goto unlock;
+  2106		}
+  2107	
+  2108		/* Avoid unnecessary overhead if debugfs is disabled */
+  2109		if (!list_empty(&hid->debug_list))
+  2110			hid_dump_report(hid, type, data, size);
+  2111	
+  2112		report = hid_get_report(report_enum, data);
+  2113	
+  2114		if (!report) {
+  2115			ret = -1;
+  2116			goto unlock;
+  2117		}
+  2118	
+  2119		if (hdrv && hdrv->raw_event && hid_match_report(hid, report)) {
+  2120			ret = hdrv->raw_event(hid, report, data, size);
+  2121			if (ret < 0)
+  2122				goto unlock;
+  2123		}
+  2124	
+  2125		ret = hid_report_raw_event(hid, type, data, size, interrupt);
+  2126	
+  2127	unlock:
+  2128		if (!lock_already_taken)
+  2129			up(&hid->driver_input_lock);
+  2130		return ret;
+  2131	}
+  2132	
+  2133	/**
+  2134	 * hid_input_report - report data from lower layer (usb, bt...)
+  2135	 *
+  2136	 * @hid: hid device
+  2137	 * @type: HID report type (HID_*_REPORT)
+  2138	 * @data: report contents
+  2139	 * @size: size of data parameter
+  2140	 * @interrupt: distinguish between interrupt and control transfers
+  2141	 *
+  2142	 * This is data entry for lower layers.
+  2143	 */
+  2144	int hid_input_report(struct hid_device *hid, enum hid_report_type type, u8 *data, u32 size,
+  2145			     int interrupt)
+  2146	{
+  2147		return __hid_input_report(hid, type, data, size, interrupt, 0,
+  2148					  false, /* from_bpf */
+  2149					  false /* lock_already_taken */);
+  2150	}
+  2151	EXPORT_SYMBOL_GPL(hid_input_report);
