+  2857	int hid_add_device(struct hid_device *hdev)
+  2858	{
+  2859		static atomic_t id = ATOMIC_INIT(0);
+  2860		int ret;
+  2861	
+  2862		if (WARN_ON(hdev->status & HID_STAT_ADDED))
+  2863			return -EBUSY;
+  2864	
+  2865		hdev->quirks = hid_lookup_quirk(hdev);
+  2866	
+  2867		/* we need to kill them here, otherwise they will stay allocated to
+  2868		 * wait for coming driver */
+  2869		if (hid_ignore(hdev))
+  2870			return -ENODEV;
+  2871	
+  2872		/*
+  2873		 * Check for the mandatory transport channel.
+  2874		 */
+  2875		 if (!hdev->ll_driver->raw_request) {
+  2876			hid_err(hdev, "transport driver missing .raw_request()\n");
+  2877			return -EINVAL;
+  2878		 }
+  2879	
+  2880		/*
+  2881		 * Read the device report descriptor once and use as template
+  2882		 * for the driver-specific modifications.
+  2883		 */
+  2884		ret = hdev->ll_driver->parse(hdev);
+  2885		if (ret)
+  2886			return ret;
+  2887		if (!hdev->dev_rdesc)
+  2888			return -ENODEV;
+  2889	
+  2890		/*
