+  2895		} else if (!hdev->group &&
+  2896			   !(hdev->quirks & HID_QUIRK_HAVE_SPECIAL_DRIVER)) {
+  2897			ret = hid_scan_report(hdev);
+  2898			if (ret)
+  2899				hid_warn(hdev, "bad device descriptor (%d)\n", ret);
+  2900		}
+  2901	
+  2902		hdev->id = atomic_inc_return(&id);
+  2903	
+  2904		/* XXX hack, any other cleaner solution after the driver core
+  2905		 * is converted to allow more than 20 bytes as the device name? */
+  2906		dev_set_name(&hdev->dev, "%04X:%04X:%04X.%04X", hdev->bus,
+  2907			     hdev->vendor, hdev->product, hdev->id);
+  2908	
+  2909		hid_debug_register(hdev, dev_name(&hdev->dev));
+  2910		ret = device_add(&hdev->dev);
+  2911		if (!ret)
+  2912			hdev->status |= HID_STAT_ADDED;
+  2913		else
+  2914			hid_debug_unregister(hdev);
+  2915	
+  2916		return ret;
+  2917	}
