+  2923	 * Allocate and initialize hid device, so that hid_destroy_device might be
+  2924	 * used to free it.
+  2925	 *
+  2926	 * New hid_device pointer is returned on success, otherwise ERR_PTR encoded
+  2927	 * error value.
+  2928	 */
+  2929	struct hid_device *hid_allocate_device(void)
+  2930	{
+  2931		struct hid_device *hdev;
+  2932		int ret = -ENOMEM;
+  2933	
+  2934		hdev = kzalloc(sizeof(*hdev), GFP_KERNEL);
+  2935		if (hdev == NULL)
+  2936			return ERR_PTR(ret);
