+  2950		kref_init(&hdev->ref);
+  2951	
+  2952		ret = hid_bpf_device_init(hdev);
+  2953		if (ret)
+  2954			goto out_err;
+  2955	
+  2956		return hdev;
+  2957	
+  2958	out_err:
+  2959		hid_destroy_device(hdev);
+  2960		return ERR_PTR(ret);
+  2961	}
